"use client";

/**
 * The users page: the team directory as a filterable, resizable table, with the
 * add / edit / delete that used to live only inside /settings.
 *
 * /settings keeps its Team Members section — nothing was moved out of it. This
 * is the same data given a real table: a search box, a role filter, paging, and
 * column widths that persist under their own `userColumns` blob.
 *
 * Admin-only, mirroring the section it grew out of. The page itself checks the
 * role so a rep who types the URL gets an explanation rather than an empty
 * table; the real boundary is /api/users, which rejects every write from a
 * non-admin regardless of what the UI offers.
 */
import { useCallback, useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { Plus, Search, Trash2, X as XIcon, Check, Camera } from "lucide-react";
import AppHeader from "@/components/AppHeader";
import UserTable, { type ManagedUser } from "@/components/UserTable";
import UserDetailPanel from "@/components/UserDetailPanel";
import MultiSelect from "@/components/MultiSelect";
import Select from "@/components/Select";
import { useLang } from "@/lib/i18n";
import { apiErrorMessage } from "@/lib/api-errors";
import { roleLabel } from "@/lib/reporting";
import { readAvatarFile, initialsOf } from "@/lib/avatar";
import { USER_COLUMNS, type ColumnPrefs } from "@/lib/user-columns";
import { useColumnLayout } from "@/lib/use-column-layout";
import type { TFn } from "@/lib/client-types";

/** Assignable roles, the same list the settings add-user form offers. */
const ROLES = ["Admin", "Sales", "CRM", "Visitor"];

type SessionUser = { name: string; initials: string; role: string; userColumns?: ColumnPrefs };

const PAGE_SIZE = 25;

const EMPTY_FORM = { name: "", username: "", email: "", password: "", role: "Sales", phone: "", jobTitle: "", notes: "", avatar: "" };

export default function UsersPage() {
  const router = useRouter();
  const { t, lang } = useLang();
  const [user, setUser] = useState<SessionUser | null>(null);
  const [darkMode, setDarkMode] = useState(false);
  const [users, setUsers] = useState<ManagedUser[]>([]);
  const [query, setQuery] = useState("");
  const [roleFilter, setRoleFilter] = useState<string[]>([]);
  const [page, setPage] = useState(1);
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState<ManagedUser | null>(null);
  const [form, setForm] = useState(EMPTY_FORM);
  const [formErr, setFormErr] = useState("");
  const [saving, setSaving] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState<ManagedUser | null>(null);
  /* The open panel is stored as a USERNAME, not a member object. The panel then
     derives from `users`, so a save or a delete in the form updates it for free —
     holding the object would leave the panel showing the pre-save values until it
     was reopened. */
  const [detailUsername, setDetailUsername] = useState<string | null>(null);
  const detail = useMemo(
    () => (detailUsername ? users.find(u => u.username === detailUsername) ?? null : null),
    [users, detailUsername],
  );

  const { columns, commit: setColumns, hydrate } = useColumnLayout(USER_COLUMNS, "userColumns");
  const rtl = lang === "ar";

  const loadUsers = useCallback(async () => {
    const r = await fetch("/api/users").catch(() => null);
    if (!r || !r.ok) return;
    const d = await r.json() as { users?: ManagedUser[] };
    setUsers(d.users ?? []);
  }, []);

  useEffect(() => {
    fetch("/api/auth/me").then(async (r) => {
      if (!r.ok) { router.replace("/login"); return; }
      const d = await r.json() as { authenticated: boolean; user?: SessionUser };
      if (!d.authenticated) { router.replace("/login"); return; }
      setUser(d.user ?? null);
      // Adopt this user's saved users-table widths, if any.
      hydrate(d.user?.userColumns ?? null);
      await loadUsers();
    }).catch(() => {});
    const stored = localStorage.getItem("rwaq-dark");
    // eslint-disable-next-line react-hooks/set-state-in-effect
    if (stored === "1") setDarkMode(true);
  }, [router, hydrate, loadUsers]);

  useEffect(() => {
    document.documentElement.setAttribute("data-theme", darkMode ? "dark" : "light");
    localStorage.setItem("rwaq-dark", darkMode ? "1" : "0");
  }, [darkMode]);

  /* Filtered on the CLIENT rather than the server: /api/users returns the whole
     team (tens of rows, not thousands), so a request per keystroke would cost
     more than the filter itself. Search and role AND together. */
  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return users.filter(u => {
      if (roleFilter.length > 0 && !roleFilter.includes(u.role)) return false;
      if (!q) return true;
      return (
        u.name.toLowerCase().includes(q) ||
        u.username.toLowerCase().includes(q) ||
        (u.email ?? "").toLowerCase().includes(q)
      );
    });
  }, [users, query, roleFilter]);

  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  // A filter change can leave the user on a page that no longer exists; clamping
  // here avoids rendering an empty table above a pager that says "page 4 of 2".
  const safePage = Math.min(page, totalPages);
  const paged = filtered.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE);
  const hasFilters = query.trim() !== "" || roleFilter.length > 0;


  const save = async () => {
    setSaving(true);
    setFormErr("");
    try {
      const res = editing
        ? await fetch("/api/users", {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            username: editing.username,
            newUsername: form.username,
            name: form.name,
            email: form.email,
            role: form.role,
            // Empty string means "clear it" — readOptional in the route turns a
            // blank into null, so blanking the notes actually unsets the column
            // rather than storing "".
            phone: form.phone,
            jobTitle: form.jobTitle,
            notes: form.notes,
            avatar: form.avatar,
          }),
        })
        : await fetch("/api/users", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(form),
        });
      const d = await res.json().catch(() => ({})) as { error?: string };
      if (!res.ok) throw new Error(apiErrorMessage(t, d.error));
      closeForm();
      await loadUsers();
    } catch (e: unknown) {
      setFormErr((e as Error).message);
    } finally {
      setSaving(false);
    }
  };

  const remove = async () => {
    if (!confirmDelete) return;
    const target = confirmDelete;
    setConfirmDelete(null);
    const res = await fetch("/api/users", {
      method: "DELETE",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username: target.username }),
    }).catch(() => null);
    if (!res || !res.ok) {
      const d = await res?.json().catch(() => ({})) as { error?: string } | undefined;
      setFormErr(apiErrorMessage(t, d?.error));
      return;
    }
    await loadUsers();
  };

  const openAdd = () => {
    setEditing(null);
    setForm(EMPTY_FORM);
    setFormErr("");
    setShowForm(true);
  };

  const openEdit = (u: ManagedUser) => {
    setEditing(u);
    // `?? ""` on every optional: the form's inputs are controlled, so a null from
    // the API has to become an empty string or React warns about switching an
    // uncontrolled input to controlled.
    setForm({
      name: u.name,
      username: u.username,
      email: u.email ?? "",
      password: "",
      role: u.role,
      phone: u.phone ?? "",
      jobTitle: u.jobTitle ?? "",
      notes: u.notes ?? "",
      avatar: u.avatar ?? "",
    });
    setFormErr("");
    setShowForm(true);
  };

  const closeForm = () => { setShowForm(false); setFormErr(""); };

  /** Reads a picked photo, downscales it, and holds the data URL in the form. */
  const pickAvatar = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    // Reset first, so choosing the SAME file twice still fires onChange.
    e.target.value = "";
    if (!file) return;
    setFormErr("");
    try {
      const dataUrl = await readAvatarFile(file);
      setForm(f => ({ ...f, avatar: dataUrl }));
    } catch (err) {
      setFormErr(err instanceof Error && err.message === "TOO_LARGE"
        ? t("settings.errAvatarTooBig")
        : t("users.photoInvalid"));
    }
  };

  /* Nothing renders until the session resolves — the nav, the page title and the
     admin-only gate all read `user`. Placed here rather than mid-function so the
     handlers above stay defined and reachable from the JSX below. */
  if (!user) {
    return <main className="shell-loading"><div className="spinner" /></main>;
  }

  return (
    <>
      <AppHeader user={user} active="users" darkMode={darkMode} onToggleDark={() => setDarkMode(d => !d)} />
      <main className="content">
        {/* `.page-header`, not `page-head`: only the former exists in globals.css
            (185-187), so `page-head` rendered this title row completely unstyled. */}
        <div className="page-header">
          <div>
            <h1>{t("users.title")}</h1>
            <p className="muted">{t("users.subtitle")}</p>
          </div>
          {user.role === "Admin" && (
            <button className="btn-primary" onClick={openAdd}><Plus size={15} />{t("settings.addUser")}</button>
          )}
        </div>

        {user.role !== "Admin" ? (
          <section className="panel"><p className="muted">{t("users.adminOnly")}</p></section>
        ) : (
          <>
            {/* Filters. Same primitives as the clients page so the two read
                identically: a search box, a multi-select, and a clear button
                that only appears once something is actually applied. */}
            <section className="filter-row">
              <div className="search-box">
                <Search size={15} />
                <input
                  placeholder={t("users.searchPh")}
                  value={query}
                  onChange={e => { setQuery(e.target.value); setPage(1); }}
                />
              </div>
              <MultiSelect
                label={t("users.allRoles")}
                options={ROLES}
                selected={roleFilter}
                onChange={v => { setRoleFilter(v); setPage(1); }}
                render={v => roleLabel(t, v)}
                t={t}
              />
              {hasFilters && (
                <button className="btn-ghost" onClick={() => { setQuery(""); setRoleFilter([]); setPage(1); }}>
                  {t("filter.clear")}
                </button>
              )}
            </section>

            <section className="panel">
              <div className="panel-heading">
                <h3>{t("users.title")} <small>{t("users.count", { n: filtered.length })}</small></h3>
              </div>
              <UserTable
                users={paged}
                columns={columns}
                onColumnsChange={setColumns}
                rtl={rtl}
                t={t as TFn}
                onEdit={openEdit}
                onDelete={setConfirmDelete}
                onOpenDetail={u => setDetailUsername(u.username)}
                /* The profile ICON goes to that person's profile page — the same
                   surface the sidebar button opens, with `?user=` scoping it to
                   one rep. `/profile` resolves the name against /api/users, so it
                   has to be the display name, not the username. Row-click keeps
                   opening the side panel. */
                onOpenProfile={u => router.push(`/profile?user=${encodeURIComponent(u.name)}`)}
              />
              {totalPages > 1 && (
                <div className="pager">
                  <button className="btn-outline btn-sm" disabled={safePage <= 1} onClick={() => setPage(p => Math.max(1, p - 1))}>{t("pager.prev")}</button>
                  <span className="muted">{t("pager.pageOf", { page: safePage, count: totalPages })}</span>
                  <button className="btn-outline btn-sm" disabled={safePage >= totalPages} onClick={() => setPage(p => Math.min(totalPages, p + 1))}>{t("pager.next")}</button>
                </div>
              )}
            </section>
          </>
        )}
      </main>


      {/* Profile side panel. Closes the panel before opening a form or the delete
          confirm, so the two overlays never stack. */}
      {detail && (
        <UserDetailPanel
          user={detail}
          onClose={() => setDetailUsername(null)}
          onOpenProfile={() => {
            // Hand the name over as a query param rather than a path segment: these
            // names carry spaces and Arabic, and /profile matches on them.
            setDetailUsername(null);
            router.push(`/profile?user=${encodeURIComponent(detail.name)}`);
          }}
          onEdit={() => { setDetailUsername(null); openEdit(detail); }}
          onDelete={() => { setDetailUsername(null); setConfirmDelete(detail); }}
          t={t as TFn}
          lang={lang}
        />
      )}

      {/* ── Add / Edit modal ──
          Uses the shared `.modal` chrome, which is capped to the viewport and
          scrolls its body — the same card the client form uses. */}
      {showForm && (
        <div className="modal-overlay" onClick={closeForm}>
          <div className="modal" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>{editing ? t("settings.editUser") : t("settings.addUser")}</h2>
              <button className="modal-close" onClick={closeForm} aria-label={t("common.close")}><XIcon size={18} /></button>
            </div>
            <div className="modal-body">
              <div className="form-grid-2">
                <Field label={t("settings.field.fullName")}>
                  <input value={form.name} onChange={e => setForm(f => ({ ...f, name: e.target.value }))} placeholder={t("settings.fullNamePh")} />
                </Field>
                <Field label={t("settings.field.username")}>
                  <input value={form.username} onChange={e => setForm(f => ({ ...f, username: e.target.value.toLowerCase() }))} placeholder={t("settings.usernamePh")} />
                </Field>
                <Field label={t("settings.field.email")}>
                  <input type="email" value={form.email} onChange={e => setForm(f => ({ ...f, email: e.target.value }))} placeholder={t("settings.emailPh")} />
                </Field>
                {/* Password is create-only: editing a user leaves the hash alone
                    rather than needing the current password to replace it. */}
                {!editing && (
                  <Field label={t("settings.field.password")}>
                    <input type="password" value={form.password} onChange={e => setForm(f => ({ ...f, password: e.target.value }))} placeholder={t("settings.passwordMinPh")} />
                  </Field>
                )}
                <Field label={t("settings.field.role")}>
                  <Select value={form.role} options={ROLES} onChange={v => setForm(f => ({ ...f, role: v }))} render={v => roleLabel(t, v)} searchable={false} t={t} />
                </Field>
                <Field label={t("users.phone")}>
                  <input dir="ltr" className="ltr-num" value={form.phone} onChange={e => setForm(f => ({ ...f, phone: e.target.value }))} />
                </Field>
                <Field label={t("users.jobTitle")}>
                  <input value={form.jobTitle} onChange={e => setForm(f => ({ ...f, jobTitle: e.target.value }))} />
                </Field>
                {/* Photo. `wide` so it spans the form: at half width the picker had
                    to sit next to the avatar, which squeezed the button until its
                    label wrapped onto a second line under the icon. `.no-detail` so
                    the row-click guard in the table ignores it. */}
                <Field label={t("users.photo")} wide>
                  <div className="avatar-upload no-detail">
                    <span className="user-avatar-lg">
                      {form.avatar ? <img src={form.avatar} alt="" /> : initialsOf(form.name || "?")}
                    </span>
                    <div className="avatar-upload-actions">
                      <label className="btn-outline avatar-upload-btn">
                        <Camera size={13} />{t("users.changePhoto")}
                        <input type="file" accept="image/*" onChange={pickAvatar} hidden />
                      </label>
                      {form.avatar && (
                        <button type="button" className="btn-text-danger" onClick={() => setForm(f => ({ ...f, avatar: "" }))}>
                          <XIcon size={13} />{t("users.removePhoto")}
                        </button>
                      )}
                    </div>
                  </div>
                </Field>
                <Field label={t("users.notes")} wide>
                  <textarea rows={3} value={form.notes} onChange={e => setForm(f => ({ ...f, notes: e.target.value }))} />
                </Field>
              </div>
              {formErr && <div className="settings-error" style={{ marginTop: 8 }}>{formErr}</div>}
            </div>
            <div className="modal-footer">
              <button className="btn-ghost" onClick={closeForm}>{t("common.cancel")}</button>
              <button className="btn-primary" onClick={save} disabled={saving}>
                <Check size={15} />{saving ? t("settings.saving") : t("common.save")}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ── Delete confirmation ── */}
      {confirmDelete && (
        <div className="modal-overlay" onClick={() => setConfirmDelete(null)}>
          <div className="modal delete-modal" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>{t("settings.deleteUserTitle")}</h2>
              <button className="modal-close" onClick={() => setConfirmDelete(null)} aria-label={t("common.close")}><XIcon size={18} /></button>
            </div>
            <div className="modal-body">
              <div className="delete-warning">
                <Trash2 size={24} />
                <div>
                  <strong>{confirmDelete.name}</strong>
                  <p>@{confirmDelete.username}</p>
                </div>
              </div>
              {formErr && <div className="settings-error" style={{ marginTop: 8 }}>{formErr}</div>}
            </div>
            <div className="modal-footer">
              <button className="btn-ghost" onClick={() => setConfirmDelete(null)}>{t("common.cancel")}</button>
              <button className="btn-danger" onClick={remove}><Trash2 size={15} />{t("common.delete")}</button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

function Field({ label, children, wide }: { label: string; children: React.ReactNode; wide?: boolean }) {
  // `wide` spans both columns of the form grid, for the fields that need the room
  // (the photo picker, the notes box).
  return (
    <div className="form-field" style={wide ? { gridColumn: "1 / -1" } : undefined}>
      <span className="form-label">{label}</span>{children}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { useLang } from "@/lib/i18n";
import { useLogo } from "@/lib/logo";
import { dateLocale } from "@/lib/format";
import { notificationMessage } from "@/lib/reporting";
import BrandMark from "@/components/BrandMark";
import {
  Bell, ChevronDown, LayoutDashboard, UsersRound, Layers, Settings, LogOut,
  Sun, Moon, Menu, X as XIcon, Archive, CheckCheck, Globe, Palette, Settings2,
  UserRound, UserCog, TableProperties,
} from "lucide-react";
import { useRouter } from "next/navigation";

export type HeaderUser = { name: string; initials: string; role?: string };
export type NavTab = "dashboard" | "clients" | "archived" | "marketing" | "metrics" | "users" | "options" | "profile" | "settings";

type Notif = { id: string; message: string; read: boolean; createdAt: string; type?: string; clientName?: string; clientId?: string | null };

const NAV: { key: NavTab; icon: React.ReactNode; adminOnly?: boolean }[] = [
  { key: "dashboard", icon: <LayoutDashboard size={16} /> },
  { key: "clients", icon: <UsersRound size={16} /> },
  { key: "archived", icon: <Archive size={16} /> },
  { key: "marketing", icon: <Layers size={16} /> },
  // The metrics page is the same campaign data as /marketing but as a plain
  // searchable table rather than charts — /marketing answers "how are we doing",
  // this one answers "find me that one campaign". Visible to every role, like
  // /marketing: the figures are company-wide.
  { key: "metrics", icon: <TableProperties size={16} /> },
  // Team directory and user CRUD. Admin-only in the UI; /api/users rejects every
  // write from any other role, so hiding the tab is about clarity, not security.
  { key: "users", icon: <UserCog size={16} />, adminOnly: true },
  // Reference-option management (statuses / channels / locations + their
  // colours). Admin-only in the UI; /api/options rejects every write from any
  // other role, so hiding the tab is about clarity, not security.
  { key: "options", icon: <Settings2 size={16} />, adminOnly: true },
  // Your own profile: your book of clients, your follow-ups, your stats. Kept in
  // the sidebar as well as the user menu, since it is as reachable as any other
  // page here. `go()` routes it directly rather than through the parent's
  // `onNavigate`, so no page has to learn about it — see the note there.
  { key: "profile", icon: <UserRound size={16} /> },
  { key: "settings", icon: <Settings size={16} /> },
];
/** The legacy localStorage copy of the avatar, for photos saved before it was DB-backed. */
function readStoredAvatar(): string {
  try { return localStorage.getItem("rwaq-avatar") ?? ""; } catch { return ""; }
}

export default function AppHeader({
  user, active, onNavigate, badge, darkMode, onToggleDark,
}: {
  user: HeaderUser;
  active?: NavTab;
  onNavigate?: (tab: NavTab) => void;
  badge?: React.ReactNode;
  darkMode: boolean;
  onToggleDark: () => void;
}) {
  const router = useRouter();
  const { t, lang, setLang } = useLang();
  const { logo } = useLogo();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [notifOpen, setNotifOpen] = useState(false);
  const [userMenuOpen, setUserMenuOpen] = useState(false);
  const [notifications, setNotifications] = useState<Notif[]>([]);
  // The uploaded profile photo. Read from the session (the DB is the source of
  // truth — it used to come only out of this browser's localStorage, so the
  // header showed initials on any other machine and the /users row for the same
  // person showed their photo). The localStorage key is still consulted as a
  // fallback so a photo uploaded before this change keeps showing.
  const [avatar, setAvatar] = useState("");
  const notifWrapRef = useRef<HTMLDivElement>(null);
  const userWrapRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    fetch("/api/auth/me").then((r) => r.json()).then((d) => {
      const l = d?.user?.language;
      if (l === "ar" || l === "en") setLang(l);
      const fromDb = typeof d?.user?.avatar === "string" ? d.user.avatar : "";
      setAvatar(fromDb || readStoredAvatar());
    }).catch(() => setAvatar(readStoredAvatar()));
  }, []);

  const refreshNotifications = () => {
    fetch("/api/notifications").then((r) => r.json()).then((d) => setNotifications(d.notifications ?? [])).catch(() => {});
  };

  useEffect(() => { refreshNotifications(); }, []);

  useEffect(() => {
    const onChange = () => refreshNotifications();
    window.addEventListener("rwaq-notifications-changed", onChange);
    return () => window.removeEventListener("rwaq-notifications-changed", onChange);
  }, []);

  // Re-read the avatar when the settings page uploads or removes one. It
  // re-reads the session rather than the storage key, so a photo set on another
  // device lands here on the next load; the event keeps the current tab instant.
  useEffect(() => {
    const readAvatar = () => {
      fetch("/api/auth/me").then((r) => r.json()).then((d) => {
        const fromDb = typeof d?.user?.avatar === "string" ? d.user.avatar : "";
        setAvatar(fromDb || readStoredAvatar());
      }).catch(() => setAvatar(readStoredAvatar()));
    };
    window.addEventListener("rwaq-avatar-changed", readAvatar);
    return () => window.removeEventListener("rwaq-avatar-changed", readAvatar);
  }, []);

  // Both header popovers close on a click anywhere outside them — the same
  // contract the filter menus keep. Without this they only ever closed on their
  // own toggle button, so the window stayed open over the page beneath it.
  useEffect(() => {
    if (!notifOpen && !userMenuOpen) return;
    const onDoc = (e: MouseEvent) => {
      const target = e.target as Node;
      if (notifWrapRef.current?.contains(target) || userWrapRef.current?.contains(target)) return;
      setNotifOpen(false);
      setUserMenuOpen(false);
    };
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, [notifOpen, userMenuOpen]);

  const unreadCount = notifications.filter((n) => !n.read).length;

  const markAllRead = async () => {
    if (unreadCount === 0) return;
    await fetch("/api/notifications", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({}) }).catch(() => {});
    setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
  };

  // Marketing is viewable by every role (campaign figures are company-wide);
  // only its write actions are admin-gated, inside the page itself. The options
  // tab is admin-only in the UI too — /api/options enforces the same rule on
  // every write, so this mirrors the server rather than replacing it.
  const visibleNav = NAV.filter((item) => !item.adminOnly || user.role === "Admin");
  const go = (tab: NavTab) => {
    setMobileMenuOpen(false);
    setNotifOpen(false);
    setUserMenuOpen(false);
    /* Two tabs are routed here rather than delegated. Every page passes its own
       `onNavigate` to rewrite the legacy tab names into URLs, and each one's
       switch ends in an `else` — so a tab they do not know about lands on
       /settings, silently. Handling these before the delegation makes it
       impossible to wire up half-way across ten pages.

       `users` was the second one, and it is the same trap: the dashboard's
       `onNavigate` has no `users` branch, so pressing Users from there — the
       page most people sit on — landed on Settings' Team Members list, which
       looks similar enough to read as a bug report rather than a routing one. */
    if (tab === "profile") { router.push("/profile"); return; }
    if (tab === "users") { router.push("/users"); return; }
    if (onNavigate) { onNavigate(tab); return; }
    if (tab === "dashboard") router.push("/");
    else if (tab === "clients") router.push("/?view=clients");
    else if (tab === "archived") router.push("/archived");
    else if (tab === "marketing") router.push("/marketing");
    else if (tab === "metrics") router.push("/metrics");
    else if (tab === "options") router.push("/options");
    // Deliberately a catch-all for `settings` only: a new tab added to NAV
    // without a branch here would silently land on /settings instead of erroring.
    else router.push("/settings");
  };

  /* /profile is a personal surface rather than a workspace tab, so it is reached
     from the user menu — and, since it was asked for, from the sidebar too. Both
     navigate directly rather than through `go()`'s `onNavigate` delegation, so
     neither depends on a page's switch knowing about it. */
  const openProfile = () => {
    setMobileMenuOpen(false);
    setNotifOpen(false);
    setUserMenuOpen(false);
    router.push("/profile");
  };

  const logout = async () => {
    setMobileMenuOpen(false);
    await fetch("/api/auth/logout", { method: "POST" });
    router.replace("/login");
  };

  /**
   * Opens the client a notification refers to, and marks it read.
   *
   * The read-mark is fired but NOT awaited: navigating is the point, and the
   * header re-reads its list on every mount anyway, so a failed mark cannot
   * strand the user on the page they asked for. Local state is updated straight
   * away so the row leaves the unread list behind them instead of lingering.
   */
  const openNotification = (n: Notif) => {
    if (!n.clientId) return;
    setNotifications((prev) => prev.map((x) => (x.id === n.id ? { ...x, read: true } : x)));
    setNotifOpen(false);
    void fetch("/api/notifications", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ id: n.id }),
    }).catch(() => undefined);
    router.push(`/clients/${n.clientId}`);
  };

  return (
    <>
      <header className="topbar">
        <div className="topbar-left">
          <button
            type="button"
            className="mobile-menu-btn"
            onClick={() => setMobileMenuOpen(true)}
            aria-label={t("header.menu")}
            title={t("header.menu")}
          >
            <Menu size={20} />
          </button>
          {/* The brand is a link home. It calls `go("dashboard")` rather than
              `router.push("/")` on purpose: the dashboard and the clients list
              are two VIEWS OF THIS ROUTE, selected by `view` state in page.tsx,
              not two URLs. Pushing "/" therefore re-fetched the same component
              with the same `view` and looked like a dead button when you were
              on the clients view. `go` prefers the `onNavigate` callback when the
              host page supplied one (this page, which resets `view`), and falls
              back to a real navigation from the standalone routes. */}
          <button
            type="button"
            className="brand-home"
            onClick={() => go("dashboard")}
            title={t("nav.dashboard")}
            aria-label={t("nav.dashboard")}
          >
            <BrandMark logo={logo} alt={t("brand.logoAlt")} />
            <span className="brand-name">rwaq</span>
          </button>
          {badge}
        </div>

        <nav className="topbar-nav">
          {visibleNav.map((item) => (
            <button key={item.key} onClick={() => go(item.key)} className={active === item.key ? "nav-active" : ""} aria-current={active === item.key ? "page" : undefined}>
              {item.icon}{t("nav." + item.key)}
            </button>
          ))}
        </nav>

        <div className="topbar-right">
          <div className="lang-switch" dir="ltr">
            <button
              type="button"
              className={lang === "ar" ? "active" : ""}
              onClick={() => setLang("ar")}
            >
              AR
            </button>
            <button
              type="button"
              className={lang === "en" ? "active" : ""}
              onClick={() => setLang("en")}
            >
              EN
            </button>
          </div>

          <button
            type="button"
            className="theme-toggle"
            onClick={onToggleDark}
            title={darkMode ? t("header.switchLight") : t("header.switchDark")}
            aria-label={darkMode ? t("header.switchLight") : t("header.switchDark")}
          >
            {darkMode ? <Sun size={16} /> : <Moon size={16} />}
          </button>

          <div className="user-dropdown" ref={notifWrapRef}>
            <button
              type="button"
              className="icon-btn"
              title={t("header.notifications")}
              onClick={() => { setNotifOpen((o) => !o); setUserMenuOpen(false); if (!notifOpen) refreshNotifications(); }}
            >
              <Bell size={16} />{unreadCount > 0 && <i />}
            </button>
            <div className={`dropdown-menu notif-menu ${notifOpen ? "open" : ""}`}>
              <div className="notif-head">
                <strong>{t("header.notifications")}</strong>
                {unreadCount > 0 && <button type="button" onClick={markAllRead}>{t("header.markAllRead")}</button>}
              </div>
              {unreadCount === 0 && (
                <div className="notif-allread"><CheckCheck size={13} /> {t("header.allCaughtUp")}</div>
              )}
              {notifications.filter((n) => !n.read).slice(0, 30).map((n) => (
                /* A <button>, because a notification is a pointer at a specific
                   client: the row was a <div>, so clicking "Sarah was assigned to
                   you" did absolutely nothing and the only working control was
                   the "View all" link at the bottom. `clientId` was already on the
                   Notification row in the schema and already coming back from
                   /api/notifications — only the header's local type dropped it, so
                   this needed no backend change.

                   A notification with no clientId (a workspace-wide message) stays
                   a plain, non-interactive row rather than a button that navigates
                   nowhere. */
                n.clientId ? (
                  <button
                    type="button"
                    key={n.id}
                    className="notif-item notif-item-btn unread"
                    onClick={() => openNotification(n)}
                  >
                    <span className="notif-new-dot" />
                    <div><strong>{notificationMessage(t, n)}</strong><small>{new Date(n.createdAt).toLocaleString(dateLocale(lang))}</small></div>
                  </button>
                ) : (
                  <div key={n.id} className="notif-item unread">
                    <span className="notif-new-dot" />
                    <div><strong>{notificationMessage(t, n)}</strong><small>{new Date(n.createdAt).toLocaleString(dateLocale(lang))}</small></div>
                  </div>
                )
              ))}
              <button
                type="button"
                className="notif-footer"
                onClick={() => { setNotifOpen(false); router.push("/notifications"); }}
              >
                {t("header.viewAll")}
              </button>
            </div>
          </div>

          <div className="user-dropdown" ref={userWrapRef}>
            <button
              type="button"
              className="user-pill"
              onClick={() => { setUserMenuOpen((o) => !o); setNotifOpen(false); }}
            >
              {avatar
                ? <span className="user-avatar user-avatar-photo"><img src={avatar} alt="" /></span>
                : <span className="user-avatar">{user.initials}</span>}
              <span>{user.name}</span>
              <ChevronDown size={14} className="chevron" />
            </button>
            <div id="app-user-menu" className={`dropdown-menu ${userMenuOpen ? "open" : ""}`}>
              {user.role && (
                <div className="menu-role"><span className={`role-badge ${user.role.toLowerCase()}`}>{user.role}</span></div>
              )}
              <button type="button" onClick={openProfile}><UserRound size={14} />{t("profile.title")}</button>
              <button type="button" onClick={() => go("settings")}><Settings size={14} />{t("nav.settings")}</button>
              <button type="button" className="dropdown-danger" onClick={logout}><LogOut size={14} />{t("header.signOut")}</button>
            </div>
          </div>
        </div>
      </header>

      {/* Responsive mobile menu drawer */}
      <div
        className={`mobile-nav-overlay ${mobileMenuOpen ? "open" : ""}`}
        onClick={() => setMobileMenuOpen(false)}
        aria-hidden={!mobileMenuOpen}
      >
        <div className="mobile-nav-panel" onClick={(e) => e.stopPropagation()}>
          <div className="mobile-nav-header">
            <div className="mobile-brand-wrap">
              {/* Same home link as the desktop bar, routed through `go` so it
                  resets the in-page view rather than re-pushing the URL the
                  dashboard and clients list already share. `go` also closes the
                  drawer, so tapping the logo does not navigate while the panel
                  stays open over the page it just navigated to. */}
              <button
                type="button"
                className="brand-home"
                onClick={() => go("dashboard")}
                title={t("nav.dashboard")}
                aria-label={t("nav.dashboard")}
              >
                <BrandMark logo={logo} alt={t("brand.logoAlt")} />
                <span className="brand-name">rwaq</span>
              </button>
              {badge}
            </div>
            <button
              type="button"
              className="mobile-nav-close"
              onClick={() => setMobileMenuOpen(false)}
              aria-label={t("common.close")}
            >
              <XIcon size={18} />
            </button>
          </div>

          <div className="mobile-user-card">
            <div className="mobile-user-avatar">{avatar ? <img src={avatar} alt="" /> : user.initials}</div>
            <div className="mobile-user-info">
              <strong>{user.name}</strong>
              {user.role && <span className={`role-badge ${user.role.toLowerCase()}`}>{user.role}</span>}
            </div>
          </div>

          <div className="mobile-nav-links">
            <div className="mobile-nav-section-title">{t("header.menu")}</div>
            {visibleNav.map((item) => (
              <button
                type="button"
                key={item.key}
                className={active === item.key ? "active" : ""}
                onClick={() => go(item.key)}
              >
                <span className="mobile-nav-icon">{item.icon}</span>
                <span className="mobile-nav-text">{t("nav." + item.key)}</span>
              </button>
            ))}
          </div>

          <div className="mobile-nav-prefs">
            <div className="mobile-nav-section-title">{t("settings.preferences")}</div>

            <div className="mobile-pref-row">
              <div className="mobile-pref-label">
                <Globe size={15} />
                <span>{t("settings.language")}</span>
              </div>
              <div className="lang-switch" dir="ltr">
                <button
                  type="button"
                  className={lang === "ar" ? "active" : ""}
                  onClick={() => setLang("ar")}
                >
                  العربية
                </button>
                <button
                  type="button"
                  className={lang === "en" ? "active" : ""}
                  onClick={() => setLang("en")}
                >
                  English
                </button>
              </div>
            </div>

            <div className="mobile-pref-row">
              <div className="mobile-pref-label">
                <Palette size={15} />
                <span>{darkMode ? t("settings.darkMode") : t("settings.lightMode")}</span>
              </div>
              <button
                type="button"
                className="mobile-theme-pill-btn"
                onClick={onToggleDark}
                title={darkMode ? t("header.switchLight") : t("header.switchDark")}
              >
                {darkMode ? <Sun size={15} /> : <Moon size={15} />}
                <span>{darkMode ? t("header.switchLight") : t("header.switchDark")}</span>
              </button>
            </div>
          </div>

          <div className="mobile-nav-footer">
            <button type="button" className="mobile-logout" onClick={logout}>
              <LogOut size={16} />
              <span>{t("header.signOut")}</span>
            </button>
          </div>
        </div>
      </div>
    </>
  );
}

"use client";

/**
 * The brand mark: the admin-uploaded logo when one exists, otherwise the
 * original "R" badge. Presentational on purpose — the caller owns `useLogo()` so
 * a page only fetches the logo once no matter how many marks it renders.
 */
export default function BrandMark({
  logo,
  alt,
  variant = "header",
  size = "sm",
}: {
  logo: string;
  alt: string;
  variant?: "header" | "login";
  /**
   * "lg" is for the mark that sits above the "Welcome back" heading; "sm" is
   * the corner badge. The modifier is applied to BOTH the uploaded logo and the
   * "R" fallback, so the card keeps the same footprint whether or not a logo
   * has been set.
   */
  size?: "sm" | "lg";
}) {
  const mod = size === "lg" ? " is-lg" : "";
  if (variant === "login") {
    // Deliberately a distinct class rather than reusing .login-v2-logo: that
    // rule paints a solid dark square for the "R" glyph, which would sit
    // behind the uploaded artwork.
    return logo
      ? <img src={logo} alt={alt} className={`login-v2-logo-img${mod}`} />
      : <span className={`login-v2-logo${mod}`}>R</span>;
  }
  return logo
    ? <img src={logo} alt={alt} className={`brand-logo${mod}`} />
    : <span className={`brand-letter${mod}`}>R</span>;
}

"use client";

/**
 * The clients data grid: resizable, reorderable, sortable, with row selection
 * and a per-cell renderer.

 * Extracted from src/app/page.tsx for the same reason as ClientFilterBar — so the
 * profile page shows a real table rather than a simplified stand-in. Both header
 * and body rows share the `.client-row` grid driven by `--ct-cols`, which is what
 * keeps them aligned while a column is being dragged.

 * Purely presentational: every action arrives as a callback, so the host decides what
 * a click means (edit, delete, archive, open detail).
 */
import { useEffect, useRef, useState } from "react";
import { Archive, MessageSquare, Pencil, Trash2 } from "lucide-react";
import StatusPill from "@/components/StatusPill";
import { useLang } from "@/lib/i18n";
import { dateLocale, isOverdue } from "@/lib/format";
import { useOptionColors } from "@/lib/option-colors";
import { channelLabel } from "@/lib/reporting";
import { optionColor } from "@/lib/ref-options";
import { CLIENT_COLUMNS, gridTemplate, type ColumnKey, type ResolvedColumn } from "@/lib/client-columns";
import type { Client, TFn } from "@/lib/client-types";

/**
 * Renders one table cell for a column key.
 *
 * A lookup rather than a switch inside the row so the header and body can never
 * drift out of column order — the grid assigns cells positionally, so one extra
 * or missing cell shifts every cell after it.
 */
function ClientCell({ col, c, t, lang, onOpenDetail, canEdit, isAdmin, onOpenEdit, onOpenDelete, onArchive }: {
  col: ResolvedColumn;
  c: Client;
  t: TFn;
  lang: string;
  onOpenDetail: (c: Client) => void;
  canEdit?: boolean;
  isAdmin?: boolean;
  onOpenEdit: (c: Client) => void;
  onOpenDelete: (ids: string[], names: string[]) => void;
  onArchive?: (id: string) => void | Promise<void>;
}) {
  // Same shared colour map as the rest of the app, so a channel recoloured on
  // the options page shows here without this component knowing the option exists.
  const colors = useOptionColors();
  switch (col.key) {
    case "id":
      return <span className="id-cell" title={t("th.id")}>#{c.id}</span>;
    case "client":
      return (
        <span className="person-cell" onClick={() => onOpenDetail(c)}>
          <b>{c.name}</b>
          <small><span className="ltr-num">{c.phoneNumber}</span></small>
          {c.notes && <span className="notes-indicator"><MessageSquare size={10} /></span>}
        </span>
      );
    case "status":
      return <StatusPill status={c.status} t={t} />;
    case "channel":
      return <span className="chan-tag"><i className="dot" style={{ background: optionColor("channels", c.acquisitionChannel, colors) }} />{channelLabel(t, c.acquisitionChannel)}</span>;
    case "project":
      return <span>{c.project}</span>;
    case "location":
      // Locations gained a colour here for the first time; previously this cell
      // was plain text with nothing to distinguish one city from another.
      return <span className="loc-tag"><i className="dot" style={{ background: optionColor("locations", c.location, colors) }} />{c.location}</span>;
    case "registeredAt":
      return <span className="muted">{c.createdAt ? new Date(c.createdAt).toLocaleDateString(dateLocale(lang)) : "—"}</span>;
    case "operation":
      return <span className="op-text">{c.operationToTake}</span>;
    case "firstContact":
      return <span className="muted">{c.firstContactPerson || "—"}</span>;
    case "secondContact":
      return <span className="muted">{c.secondContactPerson || "—"}</span>;
    case "lastUpdateDate":
      return <span className="muted">{c.lastUpdateDate ? new Date(c.lastUpdateDate).toLocaleDateString(dateLocale(lang)) : "—"}</span>;
    case "nextFollowUp":
      // An unset date reads as an em-dash rather than an empty cell, so "not set"
      // is visibly different from a blank that could be a rendering failure.
      // Overdue is the one state that needs action, so it alone is coloured.
      return c.nextFollowUpAt ? (
        <span className={isOverdue(c.nextFollowUpAt) ? "followup-cell is-overdue" : "followup-cell"}>
          {new Date(c.nextFollowUpAt).toLocaleDateString(dateLocale(lang))}
        </span>
      ) : <span className="muted">—</span>;
    case "actions":
      return (
        <span className="actions-cell no-detail">
          {canEdit && <button className="icon-btn" title={t("common.edit")} onClick={e => { e.stopPropagation(); onOpenEdit(c); }}><Pencil size={14} /></button>}
          {isAdmin && <><button className="icon-btn danger" title={t("common.delete")} onClick={e => { e.stopPropagation(); onOpenDelete([c.id], [c.name]); }}><Trash2 size={14} /></button>
            <button className="icon-btn" title={t("nav.archived")} onClick={e => { e.stopPropagation(); onArchive && onArchive(c.id); }}><Archive size={14} /></button></>}
        </span>
      );
    default:
      return null;
  }
}

export default function ClientTable({ clients, selectedIds, toggleSelect, toggleSelectAll, onOpenEdit, onOpenDelete, onOpenDetail, isAdmin, canEdit, onArchive, tableRef, columns, onColumnsChange, rtl, hideSelect, t }: {
  clients: Client[];
  selectedIds: Set<string>;
  toggleSelect: (id: string) => void;
  toggleSelectAll: () => void;
  onOpenEdit: (c: Client) => void;
  onOpenDelete: (ids: string[], names: string[]) => void;
  onOpenDetail: (c: Client) => void;
  isAdmin?: boolean;
  canEdit?: boolean;
  onArchive?: (id: string) => void | Promise<void>;
  /* `| null` on the inner type is React 19's `useRef<T>(null)` shape. Declaring it
     as `RefObject<HTMLDivElement>` made every caller that keeps a real ref fail to
     typecheck, so hosts passed `null` and lost the scroll indicators. */
  tableRef?: React.RefObject<HTMLDivElement | null> | null;
  columns: ResolvedColumn[];
  onColumnsChange: (c: ResolvedColumn[]) => void;
  rtl: boolean;
  t: TFn;
  /**
   * Hides the select checkbox column.
   *
   * For hosts that render the table as a read-only list (the profile page) —
   * a checkbox column whose tick does nothing is worse than no checkbox at all.
   */
  hideSelect?: boolean;
}) {
  const { lang } = useLang();
  const allSelected = clients.length > 0 && clients.every(c => selectedIds.has(c.id));

  // Width changes preview live during the drag and commit once on release —
  // otherwise a drag would fire a save per pixel.
  const [draft, setDraft] = useState<{ key: ColumnKey; w: number } | null>(null);
  const drag = useRef<{ key: ColumnKey; startX: number; startW: number } | null>(null);
  // Suppress text selection while dragging, or the drag selects the row text.
  useEffect(() => {
    if (!draft) return;
    const prev = document.body.style.userSelect;
    document.body.style.userSelect = "none";
    return () => { document.body.style.userSelect = prev; };
  }, [draft]);

  const startResize = (e: React.PointerEvent, col: ResolvedColumn) => {
    if (col.locked) return;
    e.preventDefault();
    e.stopPropagation();
    drag.current = { key: col.key, startX: e.clientX, startW: col.w };
    (e.currentTarget as HTMLElement).setPointerCapture?.(e.pointerId);
    setDraft({ key: col.key, w: col.w });
  };

  const onMove = (e: React.PointerEvent) => {
    const d = drag.current;
    if (!d) return;
    // In RTL the grid flows right-to-left, so moving the pointer RIGHT NARROWS
    // the column. Without this inversion every drag runs backwards for Arabic
    // users — the app's default language.
    const delta = rtl ? d.startX - e.clientX : e.clientX - d.startX;
    const col = columns.find(c => c.key === d.key);
    if (!col) return;
    setDraft({ key: d.key, w: Math.min(col.max, Math.max(col.min, d.startW + delta)) });
  };

  const endResize = () => {
    const done = draft;
    drag.current = null;
    setDraft(null);
    if (!done) return;
    onColumnsChange(columns.map(c => (c.key === done.key ? { ...c, w: done.w } : c)));
  };

  /** Double-click a divider to restore that column's default width. */
  const resetColumn = (col: ResolvedColumn) => {
    const def = CLIENT_COLUMNS.find(d => d.key === col.key);
    if (!def || col.locked) return;
    onColumnsChange(columns.map(c => (c.key === col.key ? { ...c, w: def.w } : c)));
  };

  const onResizeKey = (e: React.KeyboardEvent, col: ResolvedColumn) => {
    if (col.locked) return;
    const step = e.shiftKey ? 24 : 8;
    let w: number | null = null;
    // Arrow keys are mirrored in RTL, same as the drag.
    if (e.key === "ArrowRight") w = col.w + (rtl ? -step : step);
    else if (e.key === "ArrowLeft") w = col.w + (rtl ? step : -step);
    if (w === null) return;
    e.preventDefault();
    e.stopPropagation();
    onColumnsChange(columns.map(c => (c.key === col.key ? { ...c, w: Math.min(col.max, Math.max(col.min, w)) } : c)));
  };

  // The live drag width, so the header and every body row move together.
  const layout = draft ? columns.map(c => (c.key === draft.key ? { ...c, w: draft.w } : c)) : columns;
  const shown = layout.filter(col => !col.hidden && !(hideSelect && col.key === "select"));

  return (
    <div className="table-scroll-wrapper">
      <div className="scroll-indicator-left hidden" ref={(el) => { if (el) { const t2 = tableRef?.current; if (t2) { const check = () => { el.classList.toggle("hidden", t2.scrollLeft <= 0); }; check(); t2.addEventListener("scroll", check, { passive: true }); } } }} />
      <div className="scroll-indicator-right hidden" />
      <div
        className="client-table"
        ref={tableRef}
        /* Built from `shown`, NOT `layout`. The template must describe exactly the
           cells that are rendered: with `hideSelect` (the profile page) the select
           column produces no cell, so emitting its 30px track anyway shifted every
           remaining column one track to the left — the ids sat in the checkbox
           gutter and the row ended in a blank 50px gap. On the clients page
           `hideSelect` is off and the two are identical, so nothing changes there. */
        style={{ ["--ct-cols" as string]: gridTemplate(shown) }}
      >
        <div className="client-row client-head">
          {shown.map(col => (
            <span key={col.key} className="col-head-cell">
              {col.key === "select"
                ? <input type="checkbox" checked={allSelected} onChange={toggleSelectAll} className="cb" />
                : col.labelKey ? t(col.labelKey) : null}
              {!col.locked && (
                <span
                  className="col-resizer"
                  role="separator"
                  aria-orientation="vertical"
                  aria-label={t("cols.resize", { name: col.labelKey ? t(col.labelKey) : col.key })}
                  aria-valuenow={col.w}
                  aria-valuemin={col.min}
                  aria-valuemax={col.max}
                  tabIndex={0}
                  title={t("cols.resizeHint")}
                  onPointerDown={e => startResize(e, col)}
                  onPointerMove={onMove}
                  onPointerUp={endResize}
                  onPointerCancel={endResize}
                  onDoubleClick={e => { e.stopPropagation(); resetColumn(col); }}
                  onKeyDown={e => onResizeKey(e, col)}
                />
              )}
            </span>
          ))}
        </div>
        {clients.map(c => (
          <div className={`client-row client-row-clickable ${selectedIds.has(c.id) ? "selected" : ""}`} key={c.id} onClick={e => { (e.target as HTMLElement).tagName !== "INPUT" && (e.target as HTMLElement).tagName !== "SELECT" && !(e.target as HTMLElement).closest(".no-detail") && onOpenDetail(c) }}>
            {shown.map(col => (
              col.key === "select"
                ? <input key={col.key} type="checkbox" checked={selectedIds.has(c.id)} onChange={() => toggleSelect(c.id)} className="cb" onClick={e => e.stopPropagation()} />
                : <ClientCell key={col.key} col={col} c={c} t={t} lang={lang} onOpenDetail={onOpenDetail} canEdit={canEdit} isAdmin={isAdmin} onOpenEdit={onOpenEdit} onOpenDelete={onOpenDelete} onArchive={onArchive} />
            ))}
          </div>
        ))}
        {clients.length === 0 && <div className="empty-state">{t("clients.noResults")}</div>}
      </div>
    </div>
  );
}

